// The wilds: everything on the world map that is not one of the four areas (src/data/maps/layout.js). Two roads and
// forest. Generated by build_world.mjs into src/data/maps/wilds.js; src/data/maps/compose.js lays the areas over it.
//
//   North Road       the Downs signpost exit (downs 143,20) east to the valley's north west exit (valley 0,18)
//   Gate Road South  the town gate (willowmere 20,31) south, along the wall, east into the valley (valley 0,52)
//   the Root Stair   a spur north off the North Road to the pass down into the Rootbound (its own zone): `joins`
//
// Forest: every wilds cell that is not road or verge is solid. Trees stand on a jittered grid. A tree within 3 tiles of
// a walkable cell is a tree-line tree (`line: 1`, the 3D view builds it as a real tree); the rest is deep forest
// (`deep: 1`, the 3D view draws it as cheap canopy). Deterministic.
import { REGION_AT, WORLD_W as W, WORLD_H as H, toWorld } from '../../src/data/maps/layout.js';
import { WORLD_STAIR, STAIR as ROOTBOUND_STAIR } from './zone_rootbound.mjs';

export function build(regions) {
  const own = Array.from({ length: H }, () => new Uint8Array(W));   // 1 = an area's cell
  for (const [id, [ox, oy]] of Object.entries(REGION_AT)) {
    const z = regions[id];
    if (!z) throw new Error(`zone_wilds: no area ${id}`);
    for (let y = 0; y < z.h; y++) for (let x = 0; x < z.w; x++) own[y + oy][x + ox] = 1;
  }
  const ground = Array.from({ length: H }, (_, y) => Array.from({ length: W }, (_, x) => (own[y][x] ? ' ' : '.')));
  const coll = Array.from({ length: H }, (_, y) => Array.from({ length: W }, (_, x) => (own[y][x] ? ' ' : '#')));
  const kind = Array.from({ length: H }, () => new Uint8Array(W));  // 1 road, 2 verge
  const free = (x, y) => x >= 0 && y >= 0 && x < W && y < H && !own[y][x];

  // a smooth line through control points (Catmull-Rom), stepped finely
  const curve = (pts) => {
    const out = [];
    const P = [pts[0], ...pts, pts[pts.length - 1]];
    for (let i = 1; i < P.length - 2; i++) {
      const [p0, p1, p2, p3] = [P[i - 1], P[i], P[i + 1], P[i + 2]];
      for (let s = 0; s < 1; s += 0.02) {
        const t2 = s * s, t3 = t2 * s;
        const f = (a, b, c, d) => 0.5 * (2 * b + (-a + c) * s + (2 * a - 5 * b + 4 * c - d) * t2 + (-a + 3 * b - 3 * c + d) * t3);
        out.push([f(p0[0], p1[0], p2[0], p3[0]), f(p0[1], p1[1], p2[1], p3[1])]);
      }
    }
    out.push(pts[pts.length - 1]);
    return out;
  };
  // road: a 2-wide dirt bed (the joins are 2 tiles), 2 tiles of walkable verge either side
  const road = (pts) => {
    for (const [fx, fy] of curve(pts)) {
      const cx = Math.floor(fx), cy = Math.floor(fy);
      for (let dy = 0; dy < 2; dy++) for (let dx = 0; dx < 2; dx++) if (free(cx + dx, cy + dy)) kind[cy + dy][cx + dx] = 1;
    }
  };
  const verge = () => {
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) if (kind[y][x] === 1)
      for (let dy = -2; dy <= 3; dy++) for (let dx = -2; dx <= 3; dx++) if (free(x + dx, y + dy) && !kind[y + dy][x + dx]) kind[y + dy][x + dx] = 2;
  };

  const [dnx, dny] = toWorld('downs', 143, 20);        // last Downs cell of the exit (2 rows: 20, 21)
  const [vnx, vny] = toWorld('valley', 0, 18);         // first valley cell of its north west exit (rows 18, 19)
  const [gx, gy] = toWorld('willowmere', 20, 31);      // town gate (cols 20, 21)
  const [vsx, vsy] = toWorld('valley', 0, 52);         // valley's south west exit (rows 52, 53)
  road([[dnx + 1, dny], [dnx + 8, dny], [dnx + 18, dny - 3], [dnx + 30, dny - 4], [dnx + 42, dny - 1], [vnx - 6, vny], [vnx, vny]]);
  road([[gx, gy + 1], [gx, gy + 4], [gx + 6, gy + 7], [gx + 18, gy + 7], [gx + 27, gy + 5], [vsx - 5, vsy + 1], [vsx - 3, vsy], [vsx, vsy]]);
  verge();
  // the verges never reach into an area; the exits' own cells are on the area side

  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    if (kind[y][x] === 1) { ground[y][x] = '='; coll[y][x] = '.'; }
    else if (kind[y][x] === 2) { ground[y][x] = ','; coll[y][x] = '.'; }
  }

  // forest
  let seed = 20261121;
  const rnd = () => ((seed = (Math.imul(seed, 1103515245) + 12345) >>> 0) / 4294967296);
  const walkNear = (x, y, r) => {
    for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
      const X = x + dx, Y = y + dy;
      if (X < 0 || Y < 0 || X >= W || Y >= H) continue;
      if (own[Y][X] ? isAreaWalk(regions, X, Y) : kind[Y][X]) return true;
    }
    return false;
  };
  const decor = [], overlays = [];
  for (let y = 1; y < H; y += 2) for (let x = 0; x < W; x += 2) {
    const X = Math.min(W - 1, x + (rnd() < 0.5 ? 1 : 0)), Y = y;
    if (own[Y][X] || kind[Y][X] || kind[Y - 1][X]) continue;
    if (rnd() < 0.12) continue;
    const line = walkNear(X, Y, 3);
    decor.push(line ? { t: rnd() < 0.1 ? 'bush' : 'tree_pine', x: X, y: Y, line: 1 } : { t: 'tree_pine', x: X, y: Y, deep: 1 });
  }
  // roadside: lamps, a signpost where the North Road leaves the Downs, a milestone at the valley end, flowers
  // the nearest outer verge cell (2 tiles off the dirt, so a lamp never narrows the road)
  const outer = (x, y) => { for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) if (free(x + dx, y + dy) && kind[y + dy][x + dx] === 1) return false; return true; };
  const near = (x, y) => { for (let r = 0; r < 6; r++) for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) if (free(x + dx, y + dy) && kind[y + dy][x + dx] === 2 && outer(x + dx, y + dy)) return [x + dx, y + dy]; return null; };
  const put = (t, x, y, state) => { const p = near(x, y); if (p) { decor.push({ t, x: p[0], y: p[1], ...(state ? { state } : {}) }); coll[p[1]][p[0]] = '#'; } };
  put('signpost_arrow', dnx + 3, dny - 2);
  put('lamp_post', dnx + 20, dny - 6, 1);
  put('lamp_post', vnx - 14, vny - 3, 1);
  put('prop_milestone', vnx - 4, vny + 3);
  put('lamp_post', gx + 3, gy + 9, 1);
  put('lamp_post', gx + 20, gy + 10, 1);
  put('prop_milestone', vsx - 6, vsy + 4);
  const FL = ['flowers_white', 'flowers_yellow', 'flowers_violet', 'tuft_0', 'tuft_1', 'pebbles_0'];
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) if (kind[y][x] === 2 && coll[y][x] === '.' && rnd() < 0.12) overlays.push({ t: FL[Math.floor(rnd() * FL.length)], x, y });

  // The Root Stair (big world piece 1, 2026-11-22): a spur north off the North Road through the forest to the pass down
  // into the Rootbound (its own zone, tools/maps/zone_rootbound.mjs). Cut last, so every other wilds cell keeps its tree.
  const joins = [];
  {
    const S = WORLD_STAIR;
    const cells = [];
    for (const [fx, fy] of curve([[183, 118], [183, 111], [185, 102], [186, 93], [186, 85], [186, S.y + 2], [186, S.y]])) {
      const cx = Math.floor(fx), cy = Math.floor(fy);
      for (let dy = 0; dy < 2; dy++) for (let dx = 0; dx < 2; dx++) if (free(cx + dx, cy + dy)) cells.push([cx + dx, cy + dy]);
    }
    const spur = new Set();
    for (const [x, y] of cells) { if (kind[y][x] !== 1) { kind[y][x] = 3; ground[y][x] = '='; coll[y][x] = '.'; } spur.add(`${x},${y}`); }
    for (const [x, y] of cells) for (let dy = -2; dy <= 3; dy++) for (let dx = -2; dx <= 3; dx++) {
      const X = x + dx, Y = y + dy;
      if (!free(X, Y) || kind[Y][X] || Y < S.y) continue;
      kind[Y][X] = 4; ground[Y][X] = ','; coll[Y][X] = '.'; spur.add(`${X},${Y}`);
    }
    // the pass: the join cells at the top, walkable; the rock jaws either side
    for (let x = S.x; x < S.x + S.w; x++) { ground[S.y][x] = '='; coll[S.y][x] = '.'; spur.add(`${x},${S.y}`); kind[S.y][x] = 3; }
    for (let i = decor.length - 1; i >= 0; i--) if (spur.has(`${decor[i].x},${decor[i].y}`) || spur.has(`${decor[i].x + 1},${decor[i].y}`)) decor.splice(i, 1);
    for (let i = overlays.length - 1; i >= 0; i--) if (spur.has(`${overlays[i].x},${overlays[i].y}`)) overlays.splice(i, 1);
    // trees beside the new road are tree-line trees (the 3D view draws them in full)
    const nearSpur = (x, y) => { for (let dy = -3; dy <= 3; dy++) for (let dx = -3; dx <= 3; dx++) if (spur.has(`${x + dx},${y + dy}`)) return true; return false; };
    for (const d of decor) if (d.deep && nearSpur(d.x, d.y)) { delete d.deep; d.line = 1; }
    const sh = (x, y, s) => { let h = (Math.imul(x, 73856093) ^ Math.imul(y, 19349663) ^ Math.imul(s, 83492791)) >>> 0; h = Math.imul(h ^ (h >>> 13), 1274126177) >>> 0; return ((h ^ (h >>> 16)) >>> 0) / 4294967296; };
    for (const key of spur) { const [x, y] = key.split(',').map(Number); if (kind[y][x] === 4 && sh(x, y, 5) < 0.12) overlays.push({ t: FL[Math.floor(sh(x, y, 6) * FL.length)], x, y }); }
    const stand = (t, x, y, state) => { decor.push({ t, x, y, ...(state ? { state } : {}) }); coll[y][x] = '#'; };
    stand('x1_menhir_a', S.x - 1, S.y + 1); stand('x1_menhir_b', S.x + S.w, S.y + 1);
    stand('signpost_arrow', 186, 114);
    stand('lamp_post', 189, 96, 1);
    stand('lamp_post', 184, S.y + 5, 1);
    joins.push({ x: S.x, y: S.y, w: S.w, h: S.h, to: 'rootbound', tx: ROOTBOUND_STAIR.arrive[0], ty: ROOTBOUND_STAIR.arrive[1], dir: 'down' });
  }

  return {
    id: 'wilds', name: 'The Wilds', w: W, h: H, under: 'grass',
    legend: { '.': 'grass', ',': 'tallgrass', '=': 'dirt' },
    ground: ground.map((r) => r.join('')), collision: coll.map((r) => r.join('')),
    overlays, decor, joins,
  };
}

function isAreaWalk(regions, X, Y) {
  for (const [id, [ox, oy]] of Object.entries(REGION_AT)) {
    const z = regions[id];
    if (X >= ox && Y >= oy && X < ox + z.w && Y < oy + z.h) return z.collision[Y - oy][X - ox] === '.';
  }
  return false;
}
